以下是一个基于 **Windows 远程服务管理（SCM）** 的简单工具，可以用于在内网主机上创建、启动、停止和删除服务。该工具使用 **PowerShell** 和 **WMI（Windows Management Instrumentation）** 来管理远程服务。

---

### **工具功能**
1. **创建服务** (`Create-Service`)
2. **启动服务** (`Start-Service`)
3. **停止服务** (`Stop-Service`)
4. **删除服务** (`Remove-Service`)
5. **查看服务状态** (`Get-ServiceStatus`)
6. **批量操作** （可扩展）

---

### **工具代码（PowerShell 脚本）**
```powershell
<#
.SYNOPSIS
    远程服务管理工具（基于 SCM）
.DESCRIPTION
    通过 WMI 远程管理 Windows 服务（创建、启动、停止、删除）。
.NOTES
    需要管理员权限，目标主机需允许 WMI 远程访问。
#>

param (
    [Parameter(Mandatory=$true)]
    [string]$ComputerName,

    [Parameter(Mandatory=$true)]
    [ValidateSet("Create", "Start", "Stop", "Remove", "Status")]
    [string]$Action,

    [string]$ServiceName,
    [string]$DisplayName,
    [string]$BinaryPathName,
    [string]$StartType = "Manual",  # Auto/Manual/Disabled
    [string]$Description
)

# 检查管理员权限
if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error "需要管理员权限运行此脚本！"
    exit 1
}

# 检查目标主机是否可达
try {
    $session = New-PSSession -ComputerName $ComputerName -ErrorAction Stop
    Write-Host "连接到 $ComputerName 成功。" -ForegroundColor Green
}
catch {
    Write-Error "无法连接到 $ComputerName，请检查主机名或网络连接。"
    exit 1
}

# 根据操作执行不同的命令
switch ($Action) {
    "Create" {
        if (-not $ServiceName) { Write-Error "请指定服务名称（-ServiceName）！"; exit 1 }
        if (-not $BinaryPathName) { Write-Error "请指定服务可执行文件路径（-BinaryPathName）！"; exit 1 }

        $params = @{
            Name        = $ServiceName
            DisplayName = $DisplayName
            BinaryPathName = $BinaryPathName
            StartType   = $StartType
            Description = $Description
        }

        $scriptBlock = {
            param($params)
            $serviceParams = @{
                Name        = $params.Name
                DisplayName = $params.DisplayName
                BinaryPathName = $params.BinaryPathName
                StartType   = $params.StartType
                Description = $params.Description
            }
            try {
                $service = New-Service @serviceParams -ErrorAction Stop
                Write-Host "服务 '$($service.Name)' 创建成功！" -ForegroundColor Green
            }
            catch {
                Write-Error "创建服务失败：$_"
            }
        }

        Invoke-Command -Session $session -ScriptBlock $scriptBlock -ArgumentList @PSBoundParameters
    }

    "Start" {
        if (-not $ServiceName) { Write-Error "请指定服务名称（-ServiceName）！"; exit 1 }

        $scriptBlock = {
            param($serviceName)
            try {
                Start-Service -Name $serviceName -ErrorAction Stop
                Write-Host "服务 '$serviceName' 已启动。" -ForegroundColor Green
            }
            catch {
                Write-Error "启动服务失败：$_"
            }
        }

        Invoke-Command -Session $session -ScriptBlock $scriptBlock -ArgumentList $ServiceName
    }

    "Stop" {
        if (-not $ServiceName) { Write-Error "请指定服务名称（-ServiceName）！"; exit 1 }

        $scriptBlock = {
            param($serviceName)
            try {
                Stop-Service -Name $serviceName -Force -ErrorAction Stop
                Write-Host "服务 '$serviceName' 已停止。" -ForegroundColor Green
            }
            catch {
                Write-Error "停止服务失败：$_"
            }
        }

        Invoke-Command -Session $session -ScriptBlock $scriptBlock -ArgumentList $ServiceName
    }

    "Remove" {
        if (-not $ServiceName) { Write-Error "请指定服务名称（-ServiceName）！"; exit 1 }

        $scriptBlock = {
            param($serviceName)
            try {
                Uninstall-Service -Name $serviceName -Force -ErrorAction Stop
                Write-Host "服务 '$serviceName' 已删除。" -ForegroundColor Green
            }
            catch {
                Write-Error "删除服务失败：$_"
            }
        }

        Invoke-Command -Session $session -ScriptBlock $scriptBlock -ArgumentList $ServiceName
    }

    "Status" {
        if (-not $ServiceName) { Write-Error "请指定服务名称（-ServiceName）！"; exit 1 }

        $scriptBlock = {
            param($serviceName)
            try {
                $status = Get-Service -Name $serviceName -ErrorAction Stop
                Write-Host "服务 '$serviceName' 状态：$($status.Status)" -ForegroundColor Cyan
            }
            catch {
                Write-Error "获取服务状态失败：$_"
            }
        }

        Invoke-Command -Session $session -ScriptBlock $scriptBlock -ArgumentList $ServiceName
    }

    default {
        Write-Error "无效的操作 '$Action'！"
    }
}

# 关闭会话
Remove-PSSession -Session $session
```

