        decoder_code[-1] = decoder_code[-1].rstrip(',')
        decoder_code.append("""
    encoded_len equ $ - encoded_shellcode
""")

        return '\n'.join(decoder_code)

def main():
    parser = argparse.ArgumentParser(description='Shellcode多态编码器')
    parser.add_argument('shellcode', help='输入shellcode（十六进制字符串或二进制文件）')
    parser.add_argument('-o', '--output', help='输出文件名（默认stdout）')
    parser.add_argument('-k', '--key-length', type=int, default=4, help='密钥长度（默认4）')
    parser.add_argument('-m', '--mode', choices=['c', 'asm'], default='c',
                       help='输出模式：c（C代码）或asm（x86汇编）')

    args = parser.parse_args()

    encoder = PolymorphicShellcodeEncoder()
    encoder.key_length = args.key_length

    # 解析输入
    if args.shellcode.startswith('0x') or args.shellcode.startswith('\\x'):
        # 十六进制字符串
        try:
            shellcode = bytes.fromhex(args.shellcode[2:])
        except ValueError:
            print("无效的十六进制字符串")
            sys.exit(1)
    else:
        # 尝试作为文件读取
        try:
            with open(args.shellcode, 'rb') as f:
                shellcode = f.read()
        except IOError:
            print(f"无法读取文件: {args.shellcode}")
            sys.exit(1)

    # 编码shellcode
    encoded_shellcode, encoded_parts = encoder.encode_shellcode(shellcode)

    # 生成解码器
    if args.mode == 'c':
        decoder_code = encoder.generate_decoder(encoded_parts)
    else:
        decoder_code = encoder.generate_x86_decoder(encoded_parts)

    # 输出结果
    if args.output:
        with open(args.output, 'w') as f:
            f.write(decoder_code)
        print(f"解码器代码已保存到 {args.output}")
    else:
        print(decoder_code)

    # 输出编码后的shellcode
    print("\n编码后的shellcode（十六进制）：")
    print(' '.join(f"{b:02x}" for b in encoded_shellcode))
    print(f"\n密钥（用于解码）：{', '.join(f'0x{b:02x}' for b in encoder.generate_random_key(args.key_length))}")

if __name__ == "__main__":
