### 2.3 心跳保活机制
**客户端心跳**：
```go
func startHeartbeat(client *fasthttp.Client, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		req := fasthttp.AcquireRequest()
		defer fasthttp.ReleaseRequest(req)

		req.SetRequestURI("/api/heartbeat")
		req.Header.Set("X-Heartbeat", "1")

		resp := fasthttp.AcquireResponse()
		defer fasthttp.ReleaseResponse(resp)

		if err := client.Do(req, resp); err != nil {
			log.Println("Heartbeat failed, reconnecting...")
			reconnect()
		}
	}
}
```

**Server端心跳处理**：
```go
func handleHeartbeat(ctx *fasthttp.RequestCtx) {
	if ctx.RequestHeader.Peek("X-Heartbeat") == "1" {
		ctx.ResponseHeader.Set("X-Status", "OK")
		ctx.SetStatusCode(fasthttp.StatusOK)
		return
	}
	// 其他请求处理
}
```

